// G1 pre-probe Worker. Every route requires the x-probe-key header (a per-run secret).
import {DurableObject, WorkerEntrypoint, WorkflowEntrypoint, type WorkflowEvent, type WorkflowStep} from 'cloudflare:workers';
// @ts-ignore generated by gen-validators.mjs
import {validateProduction} from './validators.js';
// @ts-ignore generated by gen-validators.mjs
import examples from './examples.json';
import Ajv2020 from 'ajv/dist/2020.js';

interface Env {
  PROBE_DO: DurableObjectNamespace<ProbeDO>;
  PROBE_WF: Workflow;
  PROBE_KEY: string;
}
type BrokerProps = {token: string; read: string[]; writePrefix: string};
type Json = Record<string, any>;

// The container's only way out. Props are bound per container start.
export class Broker extends WorkerEntrypoint<Env, BrokerProps> {
  async fetch(request: Request) {
    const url = new URL(request.url);
    const props = this.ctx.props;
    const meta = {host: url.host, path: url.pathname, method: request.method};
    if (request.headers.get('authorization') !== `Bearer ${props.token}`) return Response.json({...meta, error: 'bad token'}, {status: 403});
    if (request.method === 'GET' && url.pathname.startsWith('/r/')) {
      const key = url.pathname.slice(3);
      if (!props.read.includes(key)) return Response.json({...meta, error: 'key not allowed'}, {status: 403});
      return new Response(`broker-ok:${key}`);
    }
    if (request.method === 'PUT' && url.pathname.startsWith('/w/')) {
      const key = url.pathname.slice(3);
      if (!key.startsWith(props.writePrefix)) return Response.json({...meta, error: 'prefix not allowed'}, {status: 403});
      const body = await request.arrayBuffer();
      if (body.byteLength > 4 << 20) return Response.json({...meta, error: 'too large'}, {status: 413});
      return Response.json({...meta, stored: key, bytes: body.byteLength});
    }
    return Response.json({...meta, error: 'not found'}, {status: 404});
  }
}

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export class ProbeDO extends DurableObject<Env> {
  token: string | null = null;
  exitInfo: Json | null = null;
  tasks = new Map<string, Json>();

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const body: Json = request.method === 'POST' ? await request.json<Json>().catch(() => ({})) : {};
    try {
      switch (url.pathname) {
        case '/start': return Response.json(await this.start(body));
        case '/state': return Response.json(await this.state());
        case '/task': return Response.json(await this.runTask(body));
        case '/result': return Response.json(this.tasks.get(body.taskId) ?? (await this.ctx.storage.get(`task:${body.taskId}`)) ?? {status: 'unknown'});
        case '/destroy': {
          const started = Date.now();
          await this.ctx.container.destroy();
          return Response.json({destroyMs: Date.now() - started, runningAfter: this.ctx.container.running});
        }
        case '/signal': this.ctx.container.signal(body.signal ?? 15); return Response.json({sentAt: Date.now()});
        case '/inactivity': await this.ctx.container.setInactivityTimeout(body.ms); return Response.json({ok: true});
        case '/snapshot': {
          const started = Date.now();
          const snapshot = await this.ctx.container.snapshotContainer({name: body.name});
          await this.ctx.storage.put('snapshot', snapshot);
          return Response.json({...snapshot, snapshotMs: Date.now() - started});
        }
        case '/wf-task': return Response.json(await this.workflowTask(body));
        default: return Response.json({error: 'unknown route'}, {status: 404});
      }
    } catch (error: any) {
      return Response.json({error: String(error?.stack ?? error)}, {status: 500});
    }
  }

  async start(body: Json) {
    if (this.ctx.container.running) return {alreadyRunning: true};
    const token = crypto.randomUUID();
    const envToken = `env-${crypto.randomUUID()}`;
    this.token = token;
    await this.ctx.storage.put('token', token);
    const options: any = {instance: body.instance ?? 'standard-3', enableInternet: false, env: {DUMMY_ENV_TOKEN: envToken}};
    if (body.snapshotId) options.containerSnapshot = {id: body.snapshotId};
    else options.image = this.ctx.container.images.render;
    const started = Date.now();
    this.ctx.container.start(options);
    const broker = (this.ctx as any).exports.Broker({props: {token, read: ['probe.txt'], writePrefix: 'out/'}});
    await this.ctx.container.interceptOutboundHttp('broker.internal', broker);
    this.exitInfo = null;
    this.ctx.container.monitor()
      .then(() => ({exit: 'clean'}), (error: any) => ({exit: 'error', exitCode: error?.exitCode, message: String(error?.message ?? error)}))
      .then(info => { this.exitInfo = {...info, at: Date.now()}; });
    const port = this.ctx.container.getTcpPort(8080);
    let last = '';
    while (Date.now() - started < 120000) {
      try {
        const response = await port.fetch('http://container/ready');
        if (response.ok) return {ready: true, readyMs: Date.now() - started, controller: await response.json(), instance: options.instance, fromSnapshot: Boolean(body.snapshotId)};
        last = `status ${response.status}`;
      } catch (error: any) { last = String(error?.message ?? error); }
      await sleep(250);
    }
    return {ready: false, readyMs: Date.now() - started, last};
  }

  async state() {
    let inspect: any;
    try { inspect = await this.ctx.container.inspect(); } catch (error: any) { inspect = {error: String(error?.message ?? error)}; }
    return {running: this.ctx.container.running, inspect, exitInfo: this.exitInfo, at: Date.now()};
  }

  async callContainer(kind: string, params: Json) {
    this.token ??= (await this.ctx.storage.get<string>('token')) ?? null;
    const response = await this.ctx.container.getTcpPort(8080).fetch('http://container/task', {
      method: 'POST', body: JSON.stringify({token: this.token, kind, params})
    });
    return response.json<Json>();
  }

  // Long tasks run in the background; the caller polls /result.
  async runTask(body: Json) {
    const taskId = crypto.randomUUID();
    this.tasks.set(taskId, {status: 'running', startedAt: Date.now()});
    const work = this.callContainer(body.kind, body.params ?? {})
      .then(result => ({status: 'done', result}), (error: any) => ({status: 'failed', error: String(error?.stack ?? error)}))
      .then(async outcome => {
        const record = {...outcome, finishedAt: Date.now()};
        this.tasks.set(taskId, record);
        await this.ctx.storage.put(`task:${taskId}`, record);
      });
    this.ctx.waitUntil(work);
    return {taskId};
  }

  // Workflow chain: start the container if needed, run the task, report back with sendEvent.
  async workflowTask(body: Json) {
    const started = await this.start({instance: body.instance ?? 'standard-1'});
    const work = this.callContainer(body.kind, body.params ?? {}).then(async result => {
      const instance = await this.env.PROBE_WF.get(body.instanceId);
      await instance.sendEvent({type: 'task-done', payload: {ok: result.ok, kind: result.kind, taskMs: result.ms, sentAt: Date.now()}});
    });
    this.ctx.waitUntil(work);
    return {accepted: true, started};
  }
}

type WorkflowParams = {doName: string; kind: string; params?: Json};
export class ProbeWorkflow extends WorkflowEntrypoint<Env, WorkflowParams> {
  async run(event: WorkflowEvent<WorkflowParams>, step: WorkflowStep) {
    const startedAt = Date.now();
    const kick = await step.do('kick container task', async () => {
      const stub = this.env.PROBE_DO.get(this.env.PROBE_DO.idFromName(event.payload.doName));
      const response = await stub.fetch('http://do/wf-task', {method: 'POST', body: JSON.stringify({
        instanceId: event.instanceId, kind: event.payload.kind, params: event.payload.params ?? {}
      })});
      return response.json<Json>();
    });
    const done = await step.waitForEvent<Json>('wait for task-done', {type: 'task-done', timeout: '15 minutes'});
    return {kick, event: done.payload, totalMs: Date.now() - startedAt};
  }
}

function ajvProbe() {
  const results: Json = {};
  const started = performance.now();
  for (const [file, value] of Object.entries(examples as Json)) {
    const valid = validateProduction(value);
    results[file] = valid ? 'valid' : (validateProduction.errors ?? []).slice(0, 3);
  }
  const standaloneMs = Math.round(performance.now() - started);
  const broken = structuredClone((examples as Json)['fact-manifest.example.json']);
  delete broken.schemaVersion;
  let runtimeCompile: string;
  try { new Ajv2020().compile({type: 'string'}); runtimeCompile = 'compiled (unexpected in Workers)'; }
  catch (error: any) { runtimeCompile = `${error?.name}: ${String(error?.message).slice(0, 160)}`; }
  return {examples: results, brokenRejected: !validateProduction(broken), standaloneMs, runtimeCompile};
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    if (request.headers.get('x-probe-key') !== env.PROBE_KEY) return new Response('forbidden', {status: 403});
    const url = new URL(request.url);
    const body: Json = request.method === 'POST' ? await request.clone().json<Json>().catch(() => ({})) : {};
    try {
      const doRoute = url.pathname.match(/^\/do\/([\w-]+)(\/[\w-]+)$/);
      if (doRoute) {
        const stub = env.PROBE_DO.get(env.PROBE_DO.idFromName(doRoute[1]));
        return stub.fetch(`http://do${doRoute[2]}`, {method: 'POST', body: JSON.stringify(body)});
      }
      if (url.pathname === '/wf/start') {
        const instance = await env.PROBE_WF.create({params: body as WorkflowParams});
        return Response.json({id: instance.id});
      }
      if (url.pathname === '/wf/status') {
        const instance = await env.PROBE_WF.get(url.searchParams.get('id')!);
        return Response.json(await instance.status());
      }
      if (url.pathname === '/ajv') return Response.json(ajvProbe());
      return new Response('not found', {status: 404});
    } catch (error: any) {
      return Response.json({error: String(error?.stack ?? error)}, {status: 500});
    }
  }
};
